-
-{{ include "mysql.validateValues" . }}
-{{ include "mysql.checkRollingTags" . }}
-{{- if and (not .Values.auth.existingSecret) (not .Values.auth.customPasswordFiles) -}}
-    {{- $secretName := include "mysql.secretName" . -}}
-    {{- $requiredPasswords := list -}}
